WITH parsed AS (SELECT id, plan, currency, tier_prices, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE plan IN ('pro', 'basic')) SELECT currency, COUNT_IF(plan = 'enterprise') AS enterprise_events, MAX(entry_price) AS max_entry_price, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS lowest_price_per_usd FROM parsed GROUP BY 1 ORDER BY enterprise_events ASC NULLS FIRST
